package org.cloudburstmc.protocol.bedrock.codec.v924.serializer;
import io.netty.buffer.ByteBuf; import lombok.AccessLevel; import lombok.RequiredArgsConstructor; import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper; import org.cloudburstmc.protocol.bedrock.codec.BedrockPacketSerializer; import org.cloudburstmc.protocol.bedrock.data.SerializableVoxelShape; import org.cloudburstmc.protocol.bedrock.packet.VoxelShapesPacket; import org.cloudburstmc.protocol.common.util.VarInts; import java.util.*;
@RequiredArgsConstructor(access=AccessLevel.PROTECTED) public class VoxelShapesSerializer_v924 implements BedrockPacketSerializer<VoxelShapesPacket>{public static final VoxelShapesSerializer_v924 INSTANCE=new VoxelShapesSerializer_v924();public void serialize(ByteBuf b,BedrockCodecHelper h,VoxelShapesPacket p){h.writeArray(b,p.getShapes(),(buf,s)->{buf.writeByte(s.getCells().getXSize());buf.writeByte(s.getCells().getYSize());buf.writeByte(s.getCells().getZSize());h.writeArray(buf,s.getCells().getStorage(),(buf2,v)->buf2.writeByte(v));h.writeArray(buf,s.getXCoordinates(),ByteBuf::writeFloatLE);h.writeArray(buf,s.getYCoordinates(),ByteBuf::writeFloatLE);h.writeArray(buf,s.getZCoordinates(),ByteBuf::writeFloatLE);});VarInts.writeUnsignedInt(b,p.getNameMap().size());p.getNameMap().forEach((k,v)->{h.writeString(b,k);b.writeShortLE(v);});}public void deserialize(ByteBuf b,BedrockCodecHelper h,VoxelShapesPacket p){List<SerializableVoxelShape>s=new ArrayList<>();h.readArray(b,s,(buf,x)->{short xs=(short)buf.readUnsignedByte(),ys=(short)buf.readUnsignedByte(),zs=(short)buf.readUnsignedByte();List<Short>st=new ArrayList<>();h.readArray(buf,st,ByteBuf::readUnsignedByte);SerializableVoxelShape.SerializableCells c=new SerializableVoxelShape.SerializableCells(xs,ys,zs,st);List<Float>xv=new ArrayList<>(),yv=new ArrayList<>(),zv=new ArrayList<>();h.readArray(buf,xv,ByteBuf::readFloatLE);h.readArray(buf,yv,ByteBuf::readFloatLE);h.readArray(buf,zv,ByteBuf::readFloatLE);return new SerializableVoxelShape(c,xv,yv,zv);});p.setShapes(s);Map<String,Integer>m=new LinkedHashMap<>();int n=VarInts.readUnsignedInt(b);for(int i=0;i<n;i++)m.put(h.readString(b),b.readUnsignedShortLE());p.setNameMap(m);}}
